// 取一段文本里每个字的读音首字母：中文走字典，英文/数字原样保留
export function initialsOf(text) {
  const out = [];
  for (const ch of String(text || '')) {
    const cp = ch.codePointAt(0);
    if (cp >= PINYIN_BASE && cp < PINYIN_BASE + PINYIN_LEN) {
      const i = cp - PINYIN_BASE;
      const p = PINYIN_PRIMARY[i];
      const s = PINYIN_SECONDARY[i];
      if (p && p !== '.') out.push([p, s && s !== '.' ? s : null]);
    } else if (/[a-z0-9]/i.test(ch)) {
      out.push([ch.toLowerCase(), null]);
    }
  }
  return out;
}

/**
 * 拼音首字母匹配：允许跳字（"gbq" 能命中《告白气球》），多音字任一首字母都算
 * 纯字母/数字的查询才走这里；其它查询由调用方做普通包含匹配
 */
export function matchPinyin(text, query) {
  const q = String(query || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!q) return true;
  const parts = initialsOf(text);
  let i = 0;
  for (const [p, s] of parts) {
    if (p === q[i] || (s && s === q[i])) i++;
    if (i >= q.length) return true;
  }
  return false;
}
